'use strict';
const assert=require('node:assert/strict'),{chromium}=require('playwright');
(async()=>{
 const browser=await chromium.launch({headless:true,args:['--no-sandbox','--enable-webgl','--use-gl=angle','--use-angle=swiftshader','--enable-unsafe-swiftshader']});
 try{
 const page=await browser.newPage({viewport:{width:393,height:852},isMobile:true,hasTouch:true});
 const errors=[];page.on('pageerror',e=>errors.push(e.message));
 const response=await page.goto('http://127.0.0.1:8765/Modo-caos/rodeados.html',{waitUntil:'load'});
 assert.equal(response.status(),200);
 await page.waitForFunction(()=>!!window.__RodeadosDebug,{timeout:18000});
 assert.equal(await page.locator('#refreshFloor').count(),1);
 assert.equal(await page.locator('#manualPlace').count(),1);
 const assets=await page.locator('script[src]').evaluateAll(elements=>elements.map(e=>e.getAttribute('src')));
 assert(assets.every(url=>url.startsWith('/Modo-caos/')),JSON.stringify(assets));
 await page.locator('#startDemo').click();
 await page.waitForFunction(()=>__RodeadosDebug.stage==='playing',{timeout:3000});
 await page.waitForFunction(()=>__RodeadosDebug.renderedRobots>0,{timeout:5000});
 assert((await page.evaluate(()=>__RodeadosDebug.game.enemies.length))>0,'actual game bots spawned');
 assert((await page.evaluate(()=>__RodeadosDebug.renderedRobots))>0,'real 3D enemy mesh exists');
 assert.equal(await page.locator('#botGuide').count(),1,'direction guidance is rendered');
 assert(await page.locator('#radarWrap').isVisible());
 const beforeScars=await page.evaluate(()=>__RodeadosDebug.floorRendering);
 assert.equal(beforeScars.plates,25);
 assert.equal(beforeScars.darkPlates,25,'war theme replaces calibration floor on all 25 tiles');
 assert.equal(beforeScars.visible,25,'tactical grid is actually rendered in WebGL');
 assert.equal(beforeScars.textured,true,'actual shared brushed-steel CanvasTexture feeds all 25 PBR meshes');
 assert.equal(beforeScars.perimeterPosts,4,'four world-locked mechanical corner posts');
 assert.equal(beforeScars.ashCount,26,'low-overhead ash atmosphere appears during combat');
 const before=await page.evaluate(()=>__RodeadosDebug.game.shots);
 await page.locator('#fire').click();
 await page.waitForTimeout(140);
 assert((await page.evaluate(()=>__RodeadosDebug.game.shots))>before);
 assert(await page.locator('#bomb').isVisible(),'Bomba Caos control must be exposed');
 await page.locator('#bomb').click();
 assert.equal(await page.evaluate(()=>__RodeadosDebug.game.bombsUsed),1,'one real area bomb launched');
 assert(await page.locator('#bomb').isDisabled(),'bombs do not spam while charging');
 await page.waitForFunction(()=>__RodeadosDebug.game.bombsUsed>0&&__RodeadosDebug.game.bombs.length===0,null,{timeout:9500});
 assert((await page.evaluate(()=>__RodeadosDebug.game.bombHits))>0,'2.5 meter area explosion deals real multi-target damage');
 const marks=await page.evaluate(()=>({wear:__RodeadosDebug.game.floorDamage,appearance:__RodeadosDebug.floorRendering}));
 assert(marks.wear.some(v=>v>0),'explosion must persist scorched virtual floor damage');
 assert(marks.appearance.scars.some(v=>v>0),'war-floor scorch rendered as visible procedural texture');
 assert.deepEqual(errors,[]);
 console.log('MODO CAOS PAGES MIRROR: PASS -- runtime loaded, 3D WebGL gameplay works, floor controls exist, shot works');
 }finally{await browser.close()}
})().catch(e=>{console.error(e);process.exitCode=1});
